# Pembaruan kaca saja. Menyimpan backup source sebelum mengganti tiga file.
# Tidak mengubah file data server, NPC, portal, reward, atau kode modul lain.
[CmdletBinding()]
param([switch]$CheckOnly)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$root = [System.IO.Path]::GetFullPath($PSScriptRoot)
$utf8 = New-Object System.Text.UTF8Encoding($false)
if (-not (Test-Path -LiteralPath (Join-Path $root 'gradlew.bat') -PathType Leaf)) {
    throw 'Letakkan install-dungeon-retry.ps1 sejajar dengan gradlew.bat di folder project vitaemanager.'
}
function Get-SourceHash([byte[]]$Bytes) {
    $text = $utf8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n").Replace("`r", "`n").TrimEnd([char]10) + "`n"
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return [System.BitConverter]::ToString($sha.ComputeHash($utf8.GetBytes($text))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}
$files = @(
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/story/DungeonData.java'; Before = '79f6467227dfe5479558bc37c05ad9aeb0d430cda1fa6b3da283c41aad721815'; After = '928b7c3810de234d53d06f8cca24939bf6029f17272bc15a7df8a657fecc6a46'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/story/DungeonCommand.java'; Before = '1685e2118fcd1e999d6649790e527bd3e52cda87b531604cfdcf4a9c7dbb2e8d'; After = '676f4b01edd150cfdad3f34e08c56b2e349aeebcf2a20618438f5c27000daf8f'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/story/DungeonService.java'; Before = 'a020dac17e3992149b1203a479cd5e5a20a98cb686e12d41c4e2e476249df0c2'; After = '93940f4cb434590b34e428b1a63bd568a10cdd6ab26fd6438a528aaba18bdc75'; Content = '' }
)
$changes = New-Object 'System.Collections.Generic.List[object]'
foreach ($entry in $files) {
    $target = Join-Path $root $entry.Path
    if (-not (Test-Path -LiteralPath $target -PathType Leaf)) { throw ('Source belum ada: ' + $entry.Path + '. Kirim source dungeon terbaru sebelum memasang pembaruan ini.') }
    $currentHash = Get-SourceHash ([System.IO.File]::ReadAllBytes($target))
    if ($currentHash -eq $entry.After) { Write-Host ('Sudah terbaru: ' + $entry.Path) -ForegroundColor Green; continue }
    if ($currentHash -ne $entry.Before) { throw ('Versi source berbeda: ' + $entry.Path + '. Tidak ada file yang diganti. Kirim DungeonData.java, DungeonCommand.java, dan DungeonService.java terbaru agar pembaruan disesuaikan.') }
    $payload = [System.Convert]::FromBase64String($entry.Content)
    if ((Get-SourceHash $payload) -ne $entry.After) { throw ('Isi installer tidak valid: ' + $entry.Path) }
    $changes.Add($entry)
    Write-Host ('Siap diperbarui: ' + $entry.Path) -ForegroundColor Cyan
}
if ($CheckOnly) { Write-Host 'Pemeriksaan selesai. Belum ada file yang diganti.' -ForegroundColor Green; return }
if ($changes.Count -eq 0) { Write-Host 'Pembaruan kaca sudah terpasang.' -ForegroundColor Green; return }
$backup = Join-Path $root ('dungeon-retry-backup-' + (Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
New-Item -ItemType Directory -Path $backup | Out-Null
foreach ($entry in $files) {
    $destination = Join-Path $backup $entry.Path
    New-Item -ItemType Directory -Path ([System.IO.Path]::GetDirectoryName($destination)) -Force | Out-Null
    Copy-Item -LiteralPath (Join-Path $root $entry.Path) -Destination $destination
}
$temporary = New-Object 'System.Collections.Generic.List[string]'
try {
    foreach ($entry in $changes) {
        $target = Join-Path $root $entry.Path
        $stage = Join-Path ([System.IO.Path]::GetDirectoryName($target)) ([System.IO.Path]::GetRandomFileName())
        $temporary.Add($stage)
        [System.IO.File]::WriteAllBytes($stage, [System.Convert]::FromBase64String($entry.Content))
        Move-Item -LiteralPath $stage -Destination $target -Force
        if ((Get-SourceHash ([System.IO.File]::ReadAllBytes($target))) -ne $entry.After) { throw ('Verifikasi gagal: ' + $entry.Path) }
    }
} catch {
    $failure = $_
    foreach ($entry in $changes) {
        try { Copy-Item -LiteralPath (Join-Path $backup $entry.Path) -Destination (Join-Path $root $entry.Path) -Force }
        catch { Write-Warning ('Pulihkan manual dari backup: ' + $entry.Path) }
    }
    throw $failure
} finally {
    foreach ($stage in $temporary) { if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Force } }
}
Write-Host ''
Write-Host 'Pembaruan kaca berhasil. Setup server tetap memakai folder plugins/vitaemanager lama.' -ForegroundColor Green
Write-Host ('Backup source: ' + $backup)
Write-Host 'Build tanpa test: .\gradlew.bat clean build -x test'
Write-Host 'Ganti JAR server saat server berhenti. Pertahankan folder data plugin.'
Write-Host 'Atur dungeon yang dipilih: /vdungeon <id> time glass 36000 dan /vdungeon <id> retries 3'
